import io,re
for p in ['HARDWARE_INTEGRATION.md','docs/BENCH_BRINGUP_RUNBOOK.md']:
    lines=io.open(p,encoding='utf-8').read().split('\n')
    bad=[]
    i=0
    while i<len(lines):
        if lines[i].strip().startswith('|') and i+1<len(lines) and re.match(r'^\s*\|[\s\-:|]+\|\s*$', lines[i+1]):
            n=lines[i].count('|')
            j=i
            while j<len(lines) and lines[j].strip().startswith('|'):
                if lines[j].count('|')!=n:
                    bad.append((j+1, lines[j].count('|'), n, lines[j][:70]))
                j+=1
            i=j
        else:
            i+=1
    print(f'--- {p}: {len(bad)} 处列数不齐')
    for b in bad[:12]: print('  行',b[0],'有',b[1],'竖线，应为',b[2],'|',b[3])
PYEOF

