131	void MotionController::Update(float dt, float current_imu_yaw_rad) {
132	  if (dt <= 0.0f) return;
133	
134	  // 1. 读取并计算转速
135	  for (int i = 0; i < kNumWheels; ++i) {
136	    int32_t current_count = encs_[i]->GetCount() * motion_cfg::kEncoderSigns[i];
137	    float pps = (current_count - last_count_[i]) / dt;
138	    last_count_[i] = current_count;
139	    float raw_rpm = (pps / motion_cfg::kPulsesPerWheelRev) * 60.0f;
140	    filtered_rpm_[i] = motion_cfg::kVelocityFilterAlpha * raw_rpm + (1.0f - motion_cfg::kVelocityFilterAlpha) * filtered_rpm_[i];
141	  }
142	
143	  // 2. 里程计更新
144	  float local_vx, local_vy, local_vw;
145	  GetVelocity(&local_vx, &local_vy, &local_vw);
146	
147	  // 累加计算小车真实走过的总路程 (用于精确定长循迹)
148	  float step_dist = std::sqrt(local_vx * local_vx + local_vy * local_vy) * dt;
149	  total_distance_ += step_dist;
150	
151	  if (need_reset_yaw_offset_) {
152	      yaw_offset_ = current_imu_yaw_rad;
153	      need_reset_yaw_offset_ = false;
154	  }
155	  imu_yaw_rel_ = NormalizeAngle(current_imu_yaw_rad - yaw_offset_);
156	  odom_yaw_ += local_vw * dt;
157	  odom_yaw_ = NormalizeAngle(odom_yaw_);
158	  pos_x_ += (local_vx * std::cos(odom_yaw_) - local_vy * std::sin(odom_yaw_)) * dt;
159	  pos_y_ += (local_vx * std::sin(odom_yaw_) + local_vy * std::cos(odom_yaw_)) * dt;
160	// ESP_LOGI(TAG,
161	//          "local_vx=%.6f, local_vy=%.6f, local_vw=%.6f, yaw=%.6f, pos_y=%.6f",
162	//          local_vx, local_vy, local_vw, odom_yaw_, pos_y_);
163	  // 3. 执行外环控制逻辑
164	  if (control_mode_ == ControlMode::kPosition) {
165	    float dx = target_pos_x_ - pos_x_;
166	    float dy = target_pos_y_ - pos_y_;
167	    float distance = std::sqrt(dx * dx + dy * dy);
168	
169	    float cmd_vx = 0.0f, vw_cmd = 0.0f;
170	    if (distance > 15.0f) {
171	      float angle_error = NormalizeAngle(std::atan2(dy, dx) - odom_yaw_);
172	      vw_cmd = pid_pos_yaw_.Calculate(angle_error, 0.0f, dt);
173	      float v_cmd_raw = pid_pos_x_.Calculate(distance, 0.0f, dt);
174	      cmd_vx = std::cos(angle_error) > 0.0f ? v_cmd_raw * std::cos(angle_error) : 0.0f;
175	    } else {
176	      float final_angle_error = NormalizeAngle(target_pos_yaw_ - odom_yaw_);
177	      vw_cmd = pid_pos_yaw_.Calculate(final_angle_error, 0.0f, dt);
178	    }
179	    CalculateKinematics(cmd_vx, 0.0f, vw_cmd);
180	  } else if (control_mode_ == ControlMode::kRelativeSeq) {
181	    float cmd_vx = 0.0f, vw_cmd = 0.0f;
182	
183	    if (seq_state_ == SeqState::kForward) {
184	      float dx = pos_x_ - seq_start_x_, dy = pos_y_ - seq_start_y_;
185	      float moved_dist = std::sqrt(dx * dx + dy * dy) * (seq_target_dist_ < 0 ? -1 : 1);
186	
187	      if (std::abs(seq_target_dist_ - moved_dist) < 10.0f) { 
188	        for (int i = 0; i < kNumWheels; ++i) {
189	          pid_vel_[i].Reset();
190	          target_vel_[i] = 0.0f;
191	        }
192	        if (std::abs(seq_target_angle_) > 0.01f) { seq_state_ = SeqState::kSettle; settle_count_ = 0; }
193	        else seq_state_ = SeqState::kIdle;
194	      } else {
195	        cmd_vx = pid_pos_x_.Calculate(seq_target_dist_, moved_dist, dt);
196	      }
197	    } else if (seq_state_ == SeqState::kSettle) {
198	      if (std::abs(local_vx) < motion_cfg::kRelativeTurnSettleVxMms ||
199	          ++settle_count_ > motion_cfg::kRelativeTurnSettleMaxCycles) {
200	        seq_start_imu_yaw_ = imu_yaw_rel_;
201	        pid_pos_yaw_.Reset();
202	        seq_stable_count_ = 0; 
203	        seq_state_ = SeqState::kTurn; 
204	      }
205	    } else if (seq_state_ == SeqState::kTurn) {
206	      float moved_angle = NormalizeAngle(imu_yaw_rel_ - seq_start_imu_yaw_);
207	      float err = NormalizeAngle(seq_target_angle_ - moved_angle);
208	      
209	      if (std::abs(err) < 0.05f && std::abs(local_vw) < 0.1f) {
210	        if (++seq_stable_count_ > 10) {
211	            seq_state_ = SeqState::kIdle;
212	        }
213	        vw_cmd = 0.0f; 
214	      } else {
215	        seq_stable_count_ = 0; 
216	        vw_cmd = pid_pos_yaw_.Calculate(seq_target_angle_, moved_angle, dt); 
217	        
218	        const float kMinVw = 0.15f; 
219	        if (vw_cmd > 0.01f && vw_cmd < kMinVw) vw_cmd = kMinVw;
220	        if (vw_cmd < -0.01f && vw_cmd > -kMinVw) vw_cmd = -kMinVw;
221	      }
222	    }
223	    CalculateKinematics(cmd_vx, 0.0f, vw_cmd);
224	  }
225	
226	  // 4. 下发电机控制指令与PID计算
227	  float max_rpm_step = max_accel_rpm_s_ * dt;
228	  bool velocity_stop_command = (control_mode_ == ControlMode::kVelocity);
229	  for (int i = 0; i < kNumWheels && velocity_stop_command; ++i) {
230	    velocity_stop_command = IsNearZero(final_target_vel_[i]);
231	  }
232	
233	  if (velocity_stop_command) {
234	    for (int i = 0; i < kNumWheels; ++i) {
235	      target_vel_[i] = 0.0f;
236	      final_target_vel_[i] = 0.0f;
237	      pid_vel_[i].Reset();
238	      motors_[i]->Brake();
239	    }
240	    return;
241	  }
242	
243	  for (int i = 0; i < kNumWheels; ++i) {
244	    if (control_mode_ == ControlMode::kRelativeSeq) {
245	      if (std::abs(final_target_vel_[i]) > std::abs(target_vel_[i])) {
246	        target_vel_[i] = MoveTowards(target_vel_[i], final_target_vel_[i], max_rpm_step);
247	      } else {
248	        target_vel_[i] = final_target_vel_[i];
249	      }
250	    } else {
251	      target_vel_[i] = final_target_vel_[i];
252	    }
253	
254	    if (std::abs(target_vel_[i]) < 0.1f) pid_vel_[i].Reset();
255	    
256	    float raw_pwm = pid_vel_[i].Calculate(target_vel_[i], filtered_rpm_[i], dt);
257	    int16_t final_pwm = ApplyDeadband(target_vel_[i], raw_pwm);
258	    
259	#if DEBUG_PID
260	    if (i == 0) {
261	      ESP_LOGI(TAG, "Mode:%d Pos:(%.1f, %.1f) Yaw:%.2f PWM_L:%d",
262	               (int)control_mode_, pos_x_, pos_y_, odom_yaw_, final_pwm);
263	    }
264	#endif
265	    motors_[i]->SetSpeed(final_pwm);
266	  }
267	}
268	
269	void MotionController::GetVelocity(float* linear_x, float* linear_y, float* angular_z) const {
270	  if (!linear_x || !linear_y || !angular_z) return;
271	
272	  float v[kNumWheels];
273	  for (int i = 0; i < kNumWheels; ++i) {
274	    v[i] = filtered_rpm_[i] * motion_cfg::kRpmToMmS;
275	  }
276	
277	  kinematics_.Forward(v, linear_x, linear_y, angular_z);
278	}
279	
280	void MotionController::Stop() {
281	  control_mode_ = ControlMode::kVelocity; 
282	  for(int i = 0; i < kNumWheels; ++i) {
283	      target_vel_[i] = 0.0f;
284	      final_target_vel_[i] = 0.0f;
285	      pid_vel_[i].Reset();
286	      motors_[i]->Brake();
287	  }
288	  pid_pos_x_.Reset(); pid_pos_y_.Reset(); pid_pos_yaw_.Reset();
289	  seq_state_ = SeqState::kIdle; 
290	}
291	
292	void MotionController::SetVelocityPidGains(float kp, float ki, float kd) {
293	  for (int i = 0; i < kNumWheels; ++i) {
294	    pid_vel_[i].SetGains(kp, ki, kd);
295	  }
