301	
302	void MotionController::SetMotorTargetVelocity(MotorID motor_id, float target_mms) {
303	  control_mode_ = ControlMode::kVelocity; 
304	  const int motor_index = static_cast<int>(motor_id);
305	  if (motor_index < 0 || motor_index >= kNumWheels) {
306	    return;
307	  }
308	  final_target_vel_[motor_index] = target_mms * motion_cfg::kMmSToRpm;
309	  if (IsNearZero(target_mms)) {
310	    target_vel_[motor_index] = 0.0f;
311	    pid_vel_[motor_index].Reset();
312	    motors_[motor_index]->Brake();
313	  }
