319	    return;
320	  }
321	
322	  control_mode_ = ControlMode::kVelocity;
323	  final_target_vel_[0] = left_mms * motion_cfg::kMmSToRpm;
324	  final_target_vel_[1] = right_mms * motion_cfg::kMmSToRpm;
