5	UltrasonicSensor::UltrasonicSensor(gpio_num_t trig_pin, gpio_num_t echo_pin) : 
6	    trig_pin_(trig_pin), echo_pin_(echo_pin), cap_timer_(NULL), cap_chan_(NULL), 
7	    timer_res_(0), cap_val_begin_of_sample_(0), task_to_notify_(NULL) {}
8	
9	bool UltrasonicSensor::Init() {
10	  gpio_config_t trig_conf = {};
11	  trig_conf.intr_type = GPIO_INTR_DISABLE;
12	  trig_conf.mode = GPIO_MODE_OUTPUT;
13	  trig_conf.pin_bit_mask = (1ULL << trig_pin_);
14	  trig_conf.pull_down_en = GPIO_PULLDOWN_DISABLE;
15	  trig_conf.pull_up_en = GPIO_PULLUP_DISABLE;
16	  gpio_config(&trig_conf);
17	  gpio_set_level(trig_pin_, 0);
18	
19	  gpio_config_t echo_conf = {};
20	  echo_conf.intr_type = GPIO_INTR_DISABLE;
21	  echo_conf.mode = GPIO_MODE_INPUT;
22	  echo_conf.pin_bit_mask = (1ULL << echo_pin_);
23	  echo_conf.pull_down_en = GPIO_PULLDOWN_ENABLE; 
24	  echo_conf.pull_up_en = GPIO_PULLUP_DISABLE;
25	  gpio_config(&echo_conf);
26	
27	  // 2. 配置 MCPWM 捕获定时器
28	  mcpwm_capture_timer_config_t cap_conf = {};
29	  cap_conf.clk_src = MCPWM_CAPTURE_CLK_SRC_DEFAULT;
30	  cap_conf.group_id = 0;
31	  if (mcpwm_new_capture_timer(&cap_conf, &cap_timer_) != ESP_OK) return false;
32	
33	  // 获取定时器实际分辨率(Hz)，用于后续在中断里快速换算微秒
34	  mcpwm_capture_timer_get_resolution(cap_timer_, &timer_res_);
35	
36	// 3. 配置 MCPWM 捕获通道（绑定到 HC-SR04 ECHO）
37	  mcpwm_capture_channel_config_t cap_ch_conf = {};
38	  cap_ch_conf.gpio_num = echo_pin_;
39	  cap_ch_conf.prescale = 1;
40	  cap_ch_conf.flags.pos_edge = true;
41	  cap_ch_conf.flags.neg_edge = true;
42	  cap_ch_conf.flags.pull_down = true;
43	  cap_ch_conf.flags.pull_up = false;
44	  // 结构体经过 {} 初始化后，其余 flags 默认皆为 0，无需手动赋值，以此兼容所有 IDF v5.x 版本
45	  
46	  if (mcpwm_new_capture_channel(cap_timer_, &cap_ch_conf, &cap_chan_) != ESP_OK) return false;
47	
48	  // 4. 注册硬件边沿中断回调 (硬件会自动同时监听上升沿和下降沿)
49	  mcpwm_capture_event_callbacks_t cbs = {};
50	  cbs.on_cap = mcpwm_isr_handler;
51	  if (mcpwm_capture_channel_register_event_callbacks(cap_chan_, &cbs, this) != ESP_OK) return false;
52	
53	  // 5. 启动硬件捕获
54	  mcpwm_capture_channel_enable(cap_chan_);
55	  mcpwm_capture_timer_enable(cap_timer_);
56	  mcpwm_capture_timer_start(cap_timer_);
57	
58	  return true;
59	}
60	
61	bool IRAM_ATTR UltrasonicSensor::mcpwm_isr_handler(
62	    mcpwm_cap_channel_handle_t cap_chan,
63	    const mcpwm_capture_event_data_t *edata,
64	    void *user_data) {
65	  UltrasonicSensor *sensor = static_cast<UltrasonicSensor *>(user_data);
66	  BaseType_t high_task_wakeup = pdFALSE;
67	
68	  if (!sensor->measurement_armed_ ||
69	      sensor->task_to_notify_ == NULL ||
70	      sensor->result_sent_) {
71	    return false;
72	  }
73	
74	  if (edata->cap_edge == MCPWM_CAP_EDGE_POS) {
75	    // 只接受第一个回波上升沿
76	    if (!sensor->echo_rise_seen_) {
77	      sensor->cap_val_begin_of_sample_ = edata->cap_value;
78	      sensor->echo_rise_seen_ = true;
79	    }
80	  } 
81	  else if (edata->cap_edge == MCPWM_CAP_EDGE_NEG) {
