1	#include "camsense_lidar.h"
2	#include "esp_log.h"
3	#include <string.h>
4	
5	static const char* TAG = "CamsenseLidar";
6	
7	CamsenseLidar::CamsenseLidar(uart_port_t uart_num, gpio_num_t tx_pin, gpio_num_t rx_pin, int baud_rate)
8	    : uart_num_(uart_num),
9	      tx_pin_(tx_pin),
10	      rx_pin_(rx_pin),
11	      baud_rate_(baud_rate),
12	      state_(0), cInfo_(0), N_(0), last_angle_(0.0f),
13	      current_point_count_(0), payload_idx_(0), expected_payload_len_(0) {
14	}
15	
16	void CamsenseLidar::Init() {
17	    uart_config_t uart_config = {};
18	    uart_config.baud_rate = baud_rate_;
19	    uart_config.data_bits = UART_DATA_8_BITS;
20	    uart_config.parity    = UART_PARITY_DISABLE;
21	    uart_config.stop_bits = UART_STOP_BITS_1;
22	    uart_config.flow_ctrl = UART_HW_FLOWCTRL_DISABLE;
23	    uart_config.source_clk = UART_SCLK_DEFAULT;
24	
25	    // 适当加大 RX 缓冲
26	    ESP_ERROR_CHECK(uart_driver_install(uart_num_, 2048, 0, 0, NULL, 0));
27	    ESP_ERROR_CHECK(uart_param_config(uart_num_, &uart_config));
28	    ESP_ERROR_CHECK(uart_set_pin(uart_num_, tx_pin_, rx_pin_, UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE));
29	
30	    ESP_LOGI(TAG, "Lidar UART initialized on Port %d, Baud %d", uart_num_, baud_rate_);
31	}
32	
33	bool CamsenseLidar::Poll(LidarPoint* out_scan, uint16_t* out_count) {
34	    size_t available = 0;
35	    uart_get_buffered_data_len(uart_num_, &available);
36	    
37	    if (available == 0) {
38	        return false;
39	    }
40	
41	    // 限制单次最大读取量，确保不会霸占 CPU（留时间给系统喂狗）
42	    if (available > 512) {
43	        available = 512; 
44	    }
45	
46	    uint8_t rx_buf[512];
47	    int read_len = uart_read_bytes(uart_num_, rx_buf, available, 0);
48	    
49	    bool circle_completed = false;
50	    
51	    // 在内存中极速跑状态机
52	    for (int i = 0; i < read_len; i++) {
53	        if (ProcessByte(rx_buf[i], out_scan, out_count)) {
54	            circle_completed = true;
55	        }
56	    }
57	    
58	    return circle_completed;
59	}
60	
61	bool CamsenseLidar::ProcessByte(uint8_t rx_byte, LidarPoint* out_scan, uint16_t* out_count) {
62	    bool circle_completed = false;
63	
64	    if (state_ == 0) {
65	        if (rx_byte == 0x55) state_ = 1;
66	    } else if (state_ == 1) {
67	        if (rx_byte == 0xAA) state_ = 2;
68	        else if (rx_byte == 0x55) state_ = 1; 
69	        else state_ = 0;
70	    } else if (state_ == 2) {
71	        cInfo_ = rx_byte;
72	        state_ = 3;
73	    } else if (state_ == 3) {
74	        N_ = rx_byte;
75	        expected_payload_len_ = N_ * cInfo_ + 8;
76	        
77	        // 【终极安全校验】：彻底封死脏数据！
78	        // Camsense协议 cInfo 必须是 2 (部分型号是3)，且单包点数 N_ 不可能超过 60
79	        if (expected_payload_len_ > MAX_LIDAR_PACKET_SIZE || cInfo_ == 0 || N_ > 60 || N_ == 0) {
80	            state_ = 0; // 只要有一点不合常理，直接当成乱码丢弃
81	        } else {
82	            payload_idx_ = 0;
83	            state_ = 4;
84	        }
85	    } else if (state_ == 4) {
86	        payload_buffer_[payload_idx_++] = rx_byte;
87	        
88	        if (payload_idx_ >= expected_payload_len_) {
89	            // 将数组稍微开大一点留足余量
90	            LidarPoint packet_points[80];
91	            uint8_t valid_points = ParsePacket(payload_buffer_, cInfo_, N_, packet_points);
92	
93	            for (uint8_t i = 0; i < valid_points; i++) {
94	                const LidarPoint& pt = packet_points[i];
95	
96	                if (pt.angle < last_angle_ - 100.0f && current_point_count_ > 50) {
97	                    if (out_scan != nullptr && out_count != nullptr) {
98	                        memcpy(out_scan, current_scan_, current_point_count_ * sizeof(LidarPoint));
99	                        *out_count = current_point_count_;
100	                    }
101	                    circle_completed = true;
102	                    current_point_count_ = 0; 
103	                }
104	
105	                if (current_point_count_ < MAX_LIDAR_POINTS_PER_SCAN) {
106	                    current_scan_[current_point_count_] = pt;
107	                    current_point_count_++;
108	                }
109	                
110	                last_angle_ = pt.angle;
111	            }
112	            state_ = 0; 
113	        }
114	    }
115	    
116	    return circle_completed;
117	}
118	
119	uint8_t CamsenseLidar::ParsePacket(const uint8_t* buffer, uint8_t cInfo, uint8_t N, LidarPoint* packet_points) {
120	    float FA = (buffer[3] - 0xA0 + buffer[2] / 256.0f) * 4.0f;
121	    int LA_start = 4 + N * cInfo;
122	    float LA = (buffer[LA_start + 1] - 0xA0 + buffer[LA_start] / 256.0f) * 4.0f;
123	
124	    if (LA < FA) LA += 360.0f;
125	    float dAngle = (N > 1) ? (LA - FA) / (N - 1) : 0.0f;
126	
127	    uint8_t valid_count = 0;
128	
129	    for (int i = 0; i < N; i++) {
130	        int idx = 4 + i * cInfo;
131	        uint16_t dist = 0;
132	        uint8_t flag = 1; 
133	
134	        if (cInfo == 0x02) { 
135	            dist = ((buffer[idx + 1] & 0x3F) << 8) | buffer[idx];
136	            flag = (buffer[idx + 1] >> 7) & 0x01;
137	        }
138	
139	        if (dist == 0) flag = 1; 
140	
141	        if (flag == 0) {  
142	            float angle = FA + dAngle * i + center_base_angle_;
143	            while (angle < 0.0f) angle += 360.0f;
144	            while (angle >= 360.0f) angle -= 360.0f;
145	            
146	            // 【硬性边界保护】：防止哪怕逃过前面校验的脏数据越界
147	            if (valid_count < 80) {
148	                packet_points[valid_count].angle = angle;
149	                packet_points[valid_count].distance = static_cast<float>(dist);
150	                valid_count++;
151	            }
152	        }
153	    }
154	    return valid_count;
155	}

