#include "app_runtime.h"

#include <stdint.h>
#include <stdio.h>

#include "board.h"
#include "board_config.h"
#include "camera_i2c_client.h"
#include "esp_log.h"
#include "esp_mac.h"
#include "esp_system.h"
#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"
#include "freertos/task.h"
#include "i2c_bus_lock.h"
#include "pid_config.h"
#include "msg/gamepad_msg.h"
#include "msg/imu_msg.h"
#include "msg/battery_msg.h"
#include "msg/lidar_msg.h"
#include "msg/motion_msg.h"
#include "msg/pid_msg.h"
#include "msg/servo_msg.h"
#include "msg/temperature_msg.h"
#include "msg/ultrasonic_msg.h"
#include "nvs_flash.h"
#include "system_globals.h"
#include "wifi_app.h"

static const char *TAG = "APP_RUNTIME";

static bool s_runtime_started = false;
static bool s_comm_task_started = false;
static TaskHandle_t s_wifi_start_task_handle = nullptr;

static void delayed_restart_task(void *p) {
    const uint32_t delay_ms = reinterpret_cast<uintptr_t>(p);
    vTaskDelay(pdMS_TO_TICKS(delay_ms));
    esp_restart();
}

static void start_comm_task(void) {
    if (s_comm_task_started) {
        return;
    }

    if (system_globals().runtime.wifi_comm_mode == WifiCommMode::kMavlinkUdp) {
        if (xTaskCreate(mavlink_udp_task, "mavlink_udp", 8192, NULL, 3, NULL) == pdPASS) {
            s_comm_task_started = true;
            ESP_LOGI(TAG, "MAVLink UDP task started");
        } else {
            ESP_LOGE(TAG, "Failed to start MAVLink UDP task");
        }
        return;
    }

    if (system_globals().runtime.wifi_comm_mode == WifiCommMode::kMavlinkUart) {
        if (xTaskCreate(mavlink_uart_task, "mavlink_uart", 8192, NULL, 3, NULL) == pdPASS) {
            s_comm_task_started = true;
            ESP_LOGI(TAG, "MAVLink UART task started");
        } else {
            ESP_LOGE(TAG, "Failed to start MAVLink UART task");
        }
        return;
    }

    if (system_globals().runtime.wifi_comm_mode != WifiCommMode::kMicroRos &&
        system_globals().runtime.wifi_comm_mode != WifiCommMode::kMicroRosUart) {
        ESP_LOGW(TAG, "Unknown communication mode: %s",
                 SystemGlobals::WifiCommModeToRuntimeValue(system_globals().runtime.wifi_comm_mode));
        return;
    }

    if (xTaskCreate(microros_task, "microros", 12288, NULL, 4, NULL) == pdPASS) {
        s_comm_task_started = true;
        ESP_LOGI(TAG, "micro-ROS task started");
    } else {
        ESP_LOGE(TAG, "Failed to start micro-ROS task");
    }
}

static void wifi_start_task(void *p) {
    const bool sta_connected = wifi_init_sta();
    if (!sta_connected) {
        wifi_init_softap();
        status_led.SetMode(StatusLedMode::kFastBlink);
    }

    xTaskCreate(wifi_provision_task, "wifi_provision", 6144, NULL, 3, NULL);
    if (sta_connected && system_globals().runtime.wifi_comm_mode != WifiCommMode::kMavlinkUart &&
        system_globals().runtime.wifi_comm_mode != WifiCommMode::kMicroRosUart) {
        start_comm_task();
    } else if (!sta_connected && system_globals().runtime.wifi_comm_mode != WifiCommMode::kMavlinkUart &&
               system_globals().runtime.wifi_comm_mode != WifiCommMode::kMicroRosUart) {
        ESP_LOGW(TAG, "STA not connected; communication task is not started");
    }

    s_wifi_start_task_handle = nullptr;
    vTaskDelete(NULL);
}

static void init_device_name(void) {
    uint8_t mac[6] = {0};
    if (esp_read_mac(mac, ESP_MAC_WIFI_STA) != ESP_OK) {
        snprintf(system_globals().runtime.device_name, sizeof(system_globals().runtime.device_name), "Maturo_UNKNOWN");
        ESP_LOGW(TAG, "Failed to read STA MAC, using fallback device name");
        return;
    }

    snprintf(
        system_globals().runtime.device_name,
        sizeof(system_globals().runtime.device_name),
        "Maturo_%02X%02X%02X%02X%02X%02X",
        mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
}

static void init_runtime_config(void) {
    WifiRuntimeConfig config = {};
    esp_err_t err = wifi_load_runtime_config(&config);
    if (err != ESP_OK && err != ESP_ERR_NVS_NOT_FOUND) {
        ESP_LOGW(TAG, "Failed to load runtime config, using defaults: %s",
                 esp_err_to_name(err));
    }

    system_globals().runtime.wifi_comm_mode = config.comm_mode;
    snprintf(system_globals().runtime.microros_agent_ip, sizeof(system_globals().runtime.microros_agent_ip), "%s",
             config.microros_agent_ip);
    system_globals().runtime.microros_agent_port = config.microros_agent_port;

    ESP_LOGI(TAG, "Runtime config: comm=%s, micro-ROS agent=%s:%u",
             SystemGlobals::WifiCommModeToRuntimeValue(system_globals().runtime.wifi_comm_mode),
             system_globals().runtime.microros_agent_ip,
             static_cast<unsigned>(system_globals().runtime.microros_agent_port));
}

static void init_pid_config(void) {
    PidMsg speed_pid = system_globals().control.speed_pid;
    esp_err_t err = pid_load_speed_config(&speed_pid);
    if (err == ESP_OK) {
        system_globals().control.speed_pid = speed_pid;
        ESP_LOGI(TAG, "Speed PID config: kp=%.3f, ki=%.3f, kd=%.3f",
                 speed_pid.kp, speed_pid.ki, speed_pid.kd);
    } else if (err == ESP_ERR_NVS_NOT_FOUND) {
        ESP_LOGI(TAG, "Speed PID config not found, using defaults: kp=%.3f, ki=%.3f, kd=%.3f",
                 system_globals().control.speed_pid.kp, system_globals().control.speed_pid.ki, system_globals().control.speed_pid.kd);
    } else {
        ESP_LOGW(TAG, "Failed to load speed PID config, using defaults: %s",
                 esp_err_to_name(err));
    }
}

static void create_runtime_queues(void) {
    system_globals().queues.imu_state = xQueueCreate(1, sizeof(ImuMsg));
    system_globals().queues.motion_state = xQueueCreate(1, sizeof(MotionMsg));
    system_globals().queues.ultrasonic_state = xQueueCreate(1, sizeof(UltrasonicMsg));
    system_globals().queues.lidar_state = xQueueCreate(1, sizeof(LidarMsg));
    system_globals().queues.gamepad_state = xQueueCreate(1, sizeof(GamepadMsg));
    system_globals().queues.temperature_state = xQueueCreate(1, sizeof(TemperatureMsg));
    system_globals().queues.battery_state = xQueueCreate(1, sizeof(BatteryMsg));
    system_globals().queues.motion_cmd = xQueueCreate(1, sizeof(MotionMsg));
    system_globals().queues.gamepad_motion_cmd = xQueueCreate(1, sizeof(MotionMsg));
    system_globals().queues.servo_cmd = xQueueCreate(1, sizeof(ServoMsg));
    system_globals().queues.speedpid_cmd = xQueueCreate(1, sizeof(PidMsg));
    if (system_globals().queues.speedpid_cmd != nullptr) {
        xQueueOverwrite(system_globals().queues.speedpid_cmd, &system_globals().control.speed_pid);
    }
    system_globals().queues.positionpid_cmd = xQueueCreate(1, sizeof(PidMsg));
}

void app_runtime_startup(void) {
    if (s_runtime_started) {
        return;
    }

    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        err = nvs_flash_init();
    }
    ESP_ERROR_CHECK(err);

    init_device_name();
    init_runtime_config();
    init_pid_config();
    shared_i2c_bus_lock_init();
    board_init();
    err = camera_i2c_client_init(leap_config::board::kImuI2cPort, CAMERA_I2C_DEFAULT_ADDRESS);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Camera I2C client init failed: %s", esp_err_to_name(err));
    }
    status_led.SetMode(StatusLedMode::kOn);

    create_runtime_queues();

    xTaskCreate(imu_task, "imu", 4096, NULL, 5, NULL);
    xTaskCreate(motion_task, "motion", 4096, NULL, 5, NULL);
    xTaskCreate(ultrasonic_task, "ultrasonic", 4096, NULL, 4, NULL);
    xTaskCreate(battery_task, "battery", 4096, NULL, 4, NULL);
    xTaskCreate(peripheral_task, "peripheral", 4096, NULL, 3, NULL);
    if (xTaskCreate(gamepad_i2c_task, "gamepad_i2c", 4096, NULL, 4, NULL) != pdPASS) {
        ESP_LOGE(TAG, "Failed to start gamepad I2C task");
    }
    xTaskCreate(lidar_task, "lidar", 8192, NULL, 4, NULL);
    if (system_globals().runtime.wifi_comm_mode == WifiCommMode::kMavlinkUart ||
        system_globals().runtime.wifi_comm_mode == WifiCommMode::kMicroRosUart) {
        start_comm_task();
    }
    xTaskCreate(camera_task, "camera_task", 4096, NULL, 3, NULL);
    xTaskCreate(wifi_start_task, "wifi_start", 4096, NULL, 3, &s_wifi_start_task_handle);

    s_runtime_started = true;
    ESP_LOGI(TAG, "Leap low runtime started");
}

void app_runtime_restart_after_delay_ms(uint32_t delay_ms) {
    xTaskCreate(
        delayed_restart_task,
        "app_restart",
        2048,
        reinterpret_cast<void *>(static_cast<uintptr_t>(delay_ms)),
        3,
        NULL);
}

