5	extern "C" bool transport_open_udp(uxrCustomTransport *transport) {
6	    auto *ctx = static_cast<UdpTransportContext *>(transport->args);
7	    ctx->fd = socket(AF_INET, SOCK_DGRAM, IPPROTO_IP);
8	    if (ctx->fd < 0) {
9	        return false;
10	    }
11	
12	    sockaddr_in local = {};
13	    local.sin_family = AF_INET;
14	    local.sin_addr.s_addr = htonl(INADDR_ANY);
15	    local.sin_port = htons(ctx->local_port);
16	    bind(ctx->fd, reinterpret_cast<sockaddr *>(&local), sizeof(local));
17	    return true;
18	}
19	
20	extern "C" bool transport_close_udp(uxrCustomTransport *transport) {
21	    auto *ctx = static_cast<UdpTransportContext *>(transport->args);
22	    if (ctx->fd >= 0) {
23	        close(ctx->fd);
24	        ctx->fd = -1;
25	    }
26	    return true;
27	}
28	
29	extern "C" size_t transport_write_udp(
30	    uxrCustomTransport *transport,
31	    const uint8_t *buf,
32	    size_t len,
33	    uint8_t *) {
34	    auto *ctx = static_cast<UdpTransportContext *>(transport->args);
35	    const int sent = sendto(
36	        ctx->fd,
37	        buf,
38	        len,
39	        0,
40	        reinterpret_cast<sockaddr *>(&ctx->remote),
41	        sizeof(ctx->remote));
42	    return sent > 0 ? static_cast<size_t>(sent) : 0;
43	}
44	
45	extern "C" size_t transport_read_udp(
46	    uxrCustomTransport *transport,
47	    uint8_t *buf,
48	    size_t len,
49	    int timeout,
50	    uint8_t *) {
51	    auto *ctx = static_cast<UdpTransportContext *>(transport->args);
52	    fd_set readfds;
53	    FD_ZERO(&readfds);
54	    FD_SET(ctx->fd, &readfds);
55	
56	    timeval tv = {};
57	    tv.tv_sec = timeout / 1000;
58	    tv.tv_usec = (timeout % 1000) * 1000;
59	    const int ret = select(ctx->fd + 1, &readfds, nullptr, nullptr, &tv);
60	    if (ret <= 0) {
61	        return 0;
62	    }
63	
64	    const int received = recv(ctx->fd, buf, len, 0);
65	    return received > 0 ? static_cast<size_t>(received) : 0;
66	}
