68	static bool ensure_uart_driver_initialized(UartTransportContext *ctx) {
69	    if (ctx == nullptr) {
70	        return false;
71	    }
72	
73	    if (s_uart_transport_initialized && uart_is_driver_installed(ctx->port)) {
74	        return true;
75	    }
76	
77	    const uart_config_t uart_config = {
78	        .baud_rate = net_cfg::kMicroRosUartBaudRate,
79	        .data_bits = UART_DATA_8_BITS,
