146	    size_t start = raw_len;
147	    for (size_t i = 0; i < raw_len; ++i) {
148	        if (raw[i] == '{') {
149	            start = i;
150	            break;
151	        }
152	    }
153	    if (start == raw_len) {
154	        out[0] = '\0';
155	        return false;
156	    }
157	
158	    size_t end = start;
159	    for (size_t i = start; i < raw_len; ++i) {
160	        if (raw[i] == '}') {
161	            end = i + 1;
162	        } else if (raw[i] == '\0' && end > start) {
163	            break;
164	        }
165	    }
166	    if (end <= start) {
167	        out[0] = '\0';
168	        return false;
169	    }
170	
171	    size_t copy_len = end - start;
172	    if (copy_len >= out_size) {
173	        copy_len = out_size - 1;
174	    }
175	    memcpy(out, raw + start, copy_len);
176	    out[copy_len] = '\0';
177	    return true;
178	}
