181	    cJSON *item = cJSON_GetObjectItemCaseSensitive(root, key);
182	    if (cJSON_IsString(item) && item->valuestring != nullptr) {
183	        copy_string(dst, dst_size, item->valuestring);
184	    } else if (dst != nullptr && dst_size > 0) {
185	        dst[0] = '\0';
186	    }
187	}
