335	    copy_string(task_command.command, sizeof(task_command.command), command);
336	    if (xQueueSend(s_command_queue, &task_command, kCommandQueueTimeout) != pdTRUE) {
337	        return ESP_ERR_TIMEOUT;
338	    }
