344	void camera_task(void *arg) {
345	    (void)arg;
346	    CameraTaskCommand task_command = {};
347	    TickType_t last_poll = xTaskGetTickCount() - kPollPeriod;
348	
349	    if (!ensure_mutex()) {
350	        ESP_LOGE(kTag, "camera_task failed to create client mutex");
351	        vTaskDelete(nullptr);
352	        return;
353	    }
354	    if (xSemaphoreTake(s_client_mutex, kClientMutexTimeout) != pdTRUE) {
355	        ESP_LOGE(kTag, "camera_task failed to take client mutex");
356	        vTaskDelete(nullptr);
357	        return;
358	    }
359	    if (!s_initialized) {
360	        xSemaphoreGive(s_client_mutex);
361	        ESP_LOGE(kTag, "camera_task started before camera_i2c_client_init");
362	        vTaskDelete(nullptr);
363	        return;
364	    }
365	    if (s_command_queue == nullptr) {
366	        s_command_queue = xQueueCreate(kCameraTaskQueueLen, sizeof(CameraTaskCommand));
367	        if (s_command_queue == nullptr) {
368	            xSemaphoreGive(s_client_mutex);
369	            ESP_LOGE(kTag, "camera_task failed to create command queue");
370	            vTaskDelete(nullptr);
371	            return;
372	        }
373	    }
374	    s_camera_task_running = true;
375	    xSemaphoreGive(s_client_mutex);
376	    ESP_LOGI(kTag, "camera_task started");
377	
378	    while (true) {
379	        const TickType_t now = xTaskGetTickCount();
380	        const TickType_t elapsed = now - last_poll;
381	        const TickType_t wait_ticks = (elapsed >= kPollPeriod) ? 0 : (kPollPeriod - elapsed);
382	
383	        if (s_command_queue != nullptr &&
384	            xQueueReceive(s_command_queue, &task_command, wait_ticks) == pdTRUE) {
385	            (void)execute_refresh_command(task_command.command, nullptr);
386	            last_poll = xTaskGetTickCount();
387	            continue;
388	        }
389	
390	        (void)execute_refresh_command("STATUS", nullptr);
391	        last_poll = xTaskGetTickCount();
392	    }
393	}
