508	    const char *password,
509	    camera_i2c_provision_format_t format,
510	    CameraI2cStatus *status) {
511	    char command[192] = {};
512	    const esp_err_t build_err = build_provision_command(
513	        ssid,
514	        password != nullptr ? password : "",
515	        format,
516	        command,
517	        sizeof(command));
518	    if (build_err != ESP_OK) {
519	        return build_err;
520	    }
521	    CameraI2cStatus before = {};
522	    (void)camera_i2c_client_get_cached_status(&before);
523	
524	    esp_err_t err = camera_i2c_client_write_command(command);
525	    if (err != ESP_OK) {
526	        return err;
527	    }
528	
529	    const TickType_t start = xTaskGetTickCount();
530	    CameraI2cStatus current = {};
531	    while ((xTaskGetTickCount() - start) < kProvisionResultTimeout) {
532	        err = camera_i2c_client_get_cached_status(&current);
533	        if (err != ESP_OK) {
534	            return err;
535	        }
536	        if (current.last_update_ms != before.last_update_ms) {
537	            if (status != nullptr) {
538	                *status = current;
539	            }
540	            return current.last_error;
541	        }
542	        vTaskDelay(kProvisionResultPoll);
543	    }
544	
545	    err = camera_i2c_client_get_cached_status(&current);
546	    if (status != nullptr && err == ESP_OK) {
547	        *status = current;
548	    }
549	    return err == ESP_OK ? ESP_ERR_TIMEOUT : err;
550	}
