import re, sys

path = "HARDWARE_INTEGRATION.md"
lines = open(path, encoding="utf-8").read().split("\n")

# 找出所有表格块，检查每块内各行的列数（忽略分隔行）
bad = []
i = 0
while i < len(lines):
    if lines[i].lstrip().startswith("|"):
        start = i
        block = []
        while i < len(lines) and lines[i].lstrip().startswith("|"):
            block.append((i + 1, lines[i]))
            i += 1
        if len(block) < 2:
            continue
        def ncols(s):
            s = s.strip()
            if s.startswith("|"): s = s[1:]
            if s.endswith("|"): s = s[:-1]
            # 粗略：按未转义的 | 切
            return len(re.split(r'(?<!\\)\|', s))
        counts = [(ln, ncols(txt)) for ln, txt in block]
        base = counts[0][1]
        for ln, c in counts:
            if c != base:
                bad.append((ln, base, c, lines[ln-1][:90]))
    else:
        i += 1

if bad:
    print(f"发现 {len(bad)} 处表格列数不一致：")
    for ln, base, c, txt in bad:
        print(f"  行 {ln}: 期望 {base} 列, 实际 {c} 列 -> {txt}")
    sys.exit(1)
else:
    print("✅ 所有 Markdown 表格列数一致")
EOF

